/* ============================================================
   MY ACCOUNT — DASHBOARD / NAV / ORDERS / ADDRESSES / DETAILS
   Matches the existing design system (Jost, #6d6e71, #222).
   Paste AFTER your existing account CSS.
   ============================================================ */

@import url('https://fonts.googleapis.com/css2?family=Jost:wght@300;400;500&display=swap');

/* ------------------------------------------------------------
   LAYOUT — sidebar nav + content side by side.
   Scoped with :has() so it never touches the login/signup page
   (that page has no .woocommerce-MyAccount-navigation).
------------------------------------------------------------ */
body.woocommerce-account .woocommerce:has(> .woocommerce-MyAccount-navigation) {
  display: flex !important;
  align-items: flex-start !important;
  gap: 60px !important;
  max-width: 1100px;
  margin: 0 auto;
}

body.woocommerce-account .woocommerce-MyAccount-navigation {
  flex: 0 0 220px;
  width: 220px;
}

body.woocommerce-account .woocommerce-MyAccount-content {
  flex: 1 1 auto;
  min-width: 0;
}

/* The theme's clearfix ::before/::after become phantom flex items and
   the flex `gap` shows up as empty bands above the nav and below the
   content. Remove them from the flex flow. */
body.woocommerce-account .woocommerce:has(> .woocommerce-MyAccount-navigation)::before,
body.woocommerce-account .woocommerce:has(> .woocommerce-MyAccount-navigation)::after {
  display: none !important;
}

/* ------------------------------------------------------------
   NAVIGATION (sidebar)
------------------------------------------------------------ */
body.woocommerce-account .woocommerce-MyAccount-navigation ul {
  list-style: none;
  margin: 0;
  padding: 0;
}

body.woocommerce-account .woocommerce-MyAccount-navigation li {
  margin: 0;
  border-bottom: 0.5px solid #e2e2e2;
}

body.woocommerce-account .woocommerce-MyAccount-navigation li a {
  display: block;
  padding: 16px 0;
  font-family: 'Jost', sans-serif;
  font-weight: 300;
  font-size: 16px;
  letter-spacing: 1px;
  text-transform: uppercase;
  color: #6d6e71;
  text-decoration: none;
  transition: color 0.25s ease;
}

body.woocommerce-account .woocommerce-MyAccount-navigation li a:hover {
  color: #222222;
}

body.woocommerce-account .woocommerce-MyAccount-navigation li.is-active a {
  color: #222222;
  font-weight: 500;
}

/* ------------------------------------------------------------
   CONTENT — headings, intro text, links
------------------------------------------------------------ */
body.woocommerce-account .woocommerce-MyAccount-content {
  font-family: 'Jost', sans-serif;
  font-weight: 300;
  font-size: 16px;
  color: #000000;
}

body.woocommerce-account .woocommerce-MyAccount-content p {
  font-family: 'Jost', sans-serif;
  font-weight: 300;
  font-size: 16px;
  color: #6d6e71;
  line-height: 1.6;
  margin: 0 0 20px;
}

body.woocommerce-account .woocommerce-MyAccount-content a,
body.woocommerce-account .woocommerce-MyAccount-navigation a {
  color: #222222;
  text-decoration: none !important;
}
body.woocommerce-account .woocommerce-MyAccount-content a:hover,
body.woocommerce-account .woocommerce-MyAccount-navigation a:hover {
  text-decoration: none !important;
}

body.woocommerce-account .woocommerce-MyAccount-content strong {
  font-weight: 500;
  color: #000000;
}

/* Section titles: "Order details", etc. (NOT the hidden col2-set ones) */
body.woocommerce-account .woocommerce-MyAccount-content > h2,
body.woocommerce-account .woocommerce-MyAccount-content h3,
body.woocommerce-account .woocommerce-order-details__title {
  font-family: 'Jost', sans-serif;
  font-weight: 300;
  font-size: 20px;
  color: #222222;
  text-transform: uppercase;
  letter-spacing: 1px;
  margin: 0 0 20px;
}

/* ------------------------------------------------------------
   ORDERS TABLE
------------------------------------------------------------ */
body.woocommerce-account .woocommerce-orders-table,
body.woocommerce-account table.shop_table {
  width: 100%;
  border: none;
  border-collapse: collapse;
  margin: 0;
}

/* Neutralize the global `tr { padding:100px !important }` from the cart CSS */
body.woocommerce-account .woocommerce-orders-table tr,
body.woocommerce-account table.shop_table tr,
body.woocommerce-account .order_details tr {
  padding: 0 !important;
}

body.woocommerce-account .woocommerce-orders-table thead th,
body.woocommerce-account table.shop_table thead th {
  font-family: 'Jost', sans-serif;
  font-weight: 300;
  font-size: 16px;
  color: #6d6e71;
  text-transform: uppercase;
  letter-spacing: 1px;
  text-align: left;
  padding: 0 10px 13px;
  border: none;
  border-bottom: 0.5px solid #B4B4B4;
  background: transparent;
}

body.woocommerce-account .woocommerce-orders-table tbody td,
body.woocommerce-account .woocommerce-orders-table tbody th,
body.woocommerce-account table.shop_table tbody td,
body.woocommerce-account table.shop_table tbody th {
