  font-weight: 300;
  font-size: 16px;
  color: #000000;
  padding: 20px 10px;
  border: none !important;
  border-bottom: 0.5px solid #e2e2e2 !important;
  background: transparent !important;
  vertical-align: middle;
  text-align: left;
