  display: inline-flex;
  align-items: center;
  justify-content: center;
  height: 40px;
  padding: 0 24px;
  background: #222222;
  color: #ffffff;
  font-family: 'Jost', sans-serif;
  font-weight: 300;
  font-size: 14px;
  text-transform: uppercase;
  letter-spacing: 1px;
  border: none;
  border-radius: 5px;
  text-decoration: none;
  transition: background 0.25s ease;
}

body.woocommerce-account a.woocommerce-button.button:hover {
  background: #444444;
  color: #ffffff;
}

/* ------------------------------------------------------------
   ORDER DETAILS TABLE (View order)
------------------------------------------------------------ */
body.woocommerce-account .order_details,
body.woocommerce-account .woocommerce-table--order-details {
  width: 100%;
  border-collapse: collapse;
  margin: 0 0 40px;
}

body.woocommerce-account .order_details th,
body.woocommerce-account .order_details td {
  font-family: 'Jost', sans-serif;
  font-weight: 300;
  font-size: 16px;
  color: #000000;
  padding: 14px 0;
  border: none;
  border-bottom: 0.5px solid #e2e2e2;
  text-align: left;
  background: transparent;
}

body.woocommerce-account .order_details thead th {
  color: #6d6e71;
  text-transform: uppercase;
  letter-spacing: 1px;
}

body.woocommerce-account .order_details td.product-total,
body.woocommerce-account .order_details tfoot td {
  text-align: right;
  color: #6d6e71;
}

body.woocommerce-account .order_details .product-quantity {
  font-weight: 300;
  color: #6d6e71;
}

body.woocommerce-account .order_details tfoot .order-total th,
body.woocommerce-account .order_details tfoot .order-total td {
  color: #222222;
  font-weight: 500;
  border-bottom: none;
}

/* ------------------------------------------------------------
   EDIT ACCOUNT / EDIT ADDRESS — form fields
------------------------------------------------------------ */
body.woocommerce-account .woocommerce-MyAccount-content form .form-row {
  display: flex;
  flex-direction: column;
  margin: 0 0 20px;
}

body.woocommerce-account .woocommerce-MyAccount-content form label {
  font-family: 'Jost', sans-serif;
  font-weight: 300;
  font-size: 16px;
  color: #000000;
  margin-bottom: 8px;
}

body.woocommerce-account .woocommerce-MyAccount-content form .required {
  color: #000000;
  border: none;
  text-decoration: none;
}

body.woocommerce-account .woocommerce-MyAccount-content form em {
  font-family: 'Jost', sans-serif;
  font-weight: 300;
  font-size: 13px;
  color: #6d6e71;
  font-style: normal;
  display: block;
  margin-top: 6px;
}

body.woocommerce-account .woocommerce-MyAccount-content form input.input-text,
body.woocommerce-account .woocommerce-MyAccount-content form input[type="text"],
body.woocommerce-account .woocommerce-MyAccount-content form input[type="email"],
body.woocommerce-account .woocommerce-MyAccount-content form input[type="password"],
body.woocommerce-account .woocommerce-MyAccount-content form input[type="tel"],
body.woocommerce-account .woocommerce-MyAccount-content form select,
body.woocommerce-account .woocommerce-MyAccount-content form .select2-container--default .select2-selection--single {
  width: 100%;
  height: 55px;
  border: 0.5px solid #bcbec0;
  border-radius: 5px;
  background: transparent;
  font-family: 'Jost', sans-serif;
  font-weight: 300;
  font-size: 16px;
  color: #000000;
  padding: 0 16px;
  outline: none;
  box-shadow: none;
  box-sizing: border-box;
  -webkit-appearance: none;
  appearance: none;
}

body.woocommerce-account .woocommerce-MyAccount-content form input:focus,
body.woocommerce-account .woocommerce-MyAccount-content form select:focus {
  border-color: #6d6e71;
}

/* Select2 vertical centering */
body.woocommerce-account .woocommerce-MyAccount-content .select2-container--default .select2-selection--single {
  display: flex;
  align-items: center;
}
body.woocommerce-account .woocommerce-MyAccount-content .select2-container--default .select2-selection--single .select2-selection__rendered {
  line-height: 55px;
  padding: 0;
}
body.woocommerce-account .woocommerce-MyAccount-content .select2-container--default .select2-selection--single .select2-selection__arrow {
  height: 55px;
}

/* Password field + show/hide button */
body.woocommerce-account .woocommerce-MyAccount-content .password-input {
  position: relative;
  display: block;
}
body.woocommerce-account .woocommerce-MyAccount-content .password-input .show-password-input {
  position: absolute;
  right: 16px;
  top: 50%;
  transform: translateY(-50%);
  cursor: pointer;
}

/* Password change fieldset */
body.woocommerce-account .woocommerce-MyAccount-content fieldset {
  border: none;
  padding: 0;
  margin: 24px 0 0;
}
body.woocommerce-account .woocommerce-MyAccount-content fieldset legend {
  font-family: 'Jost', sans-serif;
  font-weight: 300;
  font-size: 18px;
  color: #222222;
  text-transform: uppercase;
  letter-spacing: 1px;
  margin-bottom: 16px;
  padding: 0;
}

/* Save changes / submit buttons (capital .woocommerce-Button) */
body.woocommerce-account .woocommerce-MyAccount-content button.button,
body.woocommerce-account .woocommerce-MyAccount-content input[type="submit"],
body.woocommerce-account .woocommerce-MyAccount-content .woocommerce-Button.button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  height: 55px;
  min-width: 220px;
  padding: 0 40px;
  background: #222222;
  color: #ffffff;
  font-family: 'Jost', sans-serif;
  font-weight: 300;
  font-size: 18px;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  border: none;
  border-radius: 5px;
  cursor: pointer;
  margin-top: 8px;
  transition: background 0.25s ease;
}
body.woocommerce-account .woocommerce-MyAccount-content button.button:hover,
body.woocommerce-account .woocommerce-MyAccount-content input[type="submit"]:hover,
body.woocommerce-account .woocommerce-MyAccount-content .woocommerce-Button.button:hover {
  background: #444444;
  color: #ffffff;
}

/* ============================================================
   ★ THE FIX — RE-SHOW ADDRESSES
   Any .col2-set INSIDE the account content area must be visible.
   (The global .col2-set hide rule only exists to hide the
   default login/register form, which is NOT inside
   .woocommerce-MyAccount-content — so this is safe.)
   Higher specificity guarantees it wins over the hide rule.
   ============================================================ */
body.woocommerce-account .woocommerce-MyAccount-content .col2-set,
body.woocommerce-account .woocommerce-MyAccount-content .col2-set .col-1,
body.woocommerce-account .woocommerce-MyAccount-content .col2-set .col-2,
body.woocommerce-account .woocommerce-MyAccount-content .col2-set h2,
body.woocommerce-account .woocommerce-MyAccount-content .woocommerce-Address,
body.woocommerce-account .woocommerce-MyAccount-content .woocommerce-Address h2 {
  display: block !important;
}

/* Lay the two address blocks out as a 2-column grid */
body.woocommerce-account .woocommerce-MyAccount-content .woocommerce-Addresses.col2-set,
body.woocommerce-account .woocommerce-MyAccount-content .woocommerce-columns--addresses.col2-set {
  display: grid !important;
  grid-template-columns: 1fr 1fr;
  gap: 40px;
  margin-top: 30px;
}

/* Reset floats/widths WooCommerce sets on the columns.
   NOTE: this selector is more specific than the card rules below, so it
   must carry the padding we actually want (not 0), or it zeroes the box. */
body.woocommerce-account .woocommerce-MyAccount-content .col2-set .col-1,
body.woocommerce-account .woocommerce-MyAccount-content .col2-set .col-2 {
  width: auto !important;
  float: none !important;
  margin: 0 !important;
  padding: 24px !important;
  box-sizing: border-box !important;
}

/* Address / column titles (were hidden with the col2-set h2 rule) */
body.woocommerce-account .woocommerce-MyAccount-content .woocommerce-Address h2,
body.woocommerce-account .woocommerce-MyAccount-content .woocommerce-column__title {
  display: block !important;
  font-family: 'Jost', sans-serif !important;
  font-weight: 300 !important;
  font-size: 18px !important;
  color: #222222 !important;
  text-transform: uppercase !important;
  letter-spacing: 1px !important;
  margin: 0 0 12px !important;
}

/* Address card (Addresses tab) */
body.woocommerce-account .woocommerce-Address {
  border: 0.5px solid #bcbec0;
  border-radius: 5px;
  padding: 24px;
}

/* --- VIEW ORDER: customer (billing / shipping) details ---
   This section renders OUTSIDE .woocommerce-MyAccount-content, so the
   grid is applied straight on the section. The first (content-scoped)
   selector wins over the general col2-set "un-hide" rule when it IS
   inside; the second covers the outside case. */
body.woocommerce-account .woocommerce-MyAccount-content .woocommerce-columns--addresses.col2-set,
body.woocommerce-account .woocommerce-columns--addresses.col2-set {
  display: grid !important;
  grid-template-columns: 1fr 1fr;
  gap: 40px;
  align-items: start;
  width: 100% !important;
  float: none !important;
  margin: 30px 0 0 !important;
}

/* The .col2-set clearfix ::before/::after become extra GRID items and
   push billing/shipping into a broken 2x2 (empty top-left & bottom-right).
   Remove them so only the two real columns remain. Covers the Addresses
   tab grid too. */
body.woocommerce-account .woocommerce-MyAccount-content .col2-set::before,
body.woocommerce-account .woocommerce-MyAccount-content .col2-set::after,
body.woocommerce-account .woocommerce-columns--addresses.col2-set::before,
body.woocommerce-account .woocommerce-columns--addresses.col2-set::after {
  content: none !important;
  display: none !important;
}

body.woocommerce-account .woocommerce-columns--addresses .col-1,
body.woocommerce-account .woocommerce-columns--addresses .col-2,
body.woocommerce-account .woocommerce-customer-details .woocommerce-column {
  width: auto !important;
  float: none !important;
  margin: 0 !important;
  padding: 24px !important;
  border: 0.5px solid #bcbec0 !important;
  border-radius: 5px !important;
  box-sizing: border-box;
}

/* Kill WooCommerce's default border on the inner <address>
   so it isn't a box-inside-a-box */
body.woocommerce-account .woocommerce-customer-details address,
body.woocommerce-account .woocommerce-column address,
body.woocommerce-account .woocommerce-Address address {
  border: none !important;
  padding: 0 !important;
  margin: 0 !important;
  width: 100% !important;
}

body.woocommerce-account .woocommerce-Address-title {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 12px;
}
body.woocommerce-account .woocommerce-Address-title h2 {
  margin: 0 !important;
}

body.woocommerce-account .woocommerce-Address-title .edit {
  font-family: 'Jost', sans-serif;
  font-weight: 300;
  font-size: 14px;
  color: #6d6e71;
  text-decoration: none;
  white-space: nowrap;
}
body.woocommerce-account .woocommerce-Address-title .edit:hover {
  color: #222222;
  text-decoration: none;
}

body.woocommerce-account .woocommerce-MyAccount-content address,
body.woocommerce-account .woocommerce-customer-details address,
body.woocommerce-account .woocommerce-Address address {
  font-family: 'Jost', sans-serif;
  font-weight: 300;
  font-size: 16px;
  font-style: normal;
  line-height: 1.7;
  color: #000000;
  margin: 0;
}

body.woocommerce-account .woocommerce-customer-details--phone,
body.woocommerce-account .woocommerce-customer-details--email {
  color: #6d6e71 !important;
  margin: 8px 0 0 !important;
}

/* ============================================================
   MOBILE
   ============================================================ */
@media (max-width: 768px) {

  body.woocommerce-account .woocommerce:has(> .woocommerce-MyAccount-navigation) {
    flex-direction: column;
    gap: 30px;
  }

  body.woocommerce-account .woocommerce-MyAccount-navigation {
    flex: 1 1 auto;
    width: 100%;
  }

  body.woocommerce-account .woocommerce-MyAccount-content > h2,
  body.woocommerce-account .woocommerce-MyAccount-content h3,
  body.woocommerce-account .woocommerce-order-details__title {
    font-size: 18px;
  }

  /* Addresses stack */
  body.woocommerce-account .woocommerce-MyAccount-content .woocommerce-Addresses.col2-set,
  body.woocommerce-account .woocommerce-columns--addresses.col2-set {
    grid-template-columns: 1fr !important;
    gap: 20px;
  }

  /* Responsive orders table (stacked rows) */
  body.woocommerce-account table.shop_table_responsive thead {
    display: none;
  }
  body.woocommerce-account table.shop_table_responsive tbody tr {
    display: block;
    border-bottom: 0.5px solid #e2e2e2;
    padding: 16px 0 !important;
  }
