    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 6px 0 !important;
    border: none !important;
    text-align: right;
  }
  body.woocommerce-account table.shop_table_responsive tbody td::before {
    content: attr(data-title);
    font-weight: 500;
    color: #6d6e71;
    text-transform: uppercase;
    font-size: 13px;
    letter-spacing: 1px;
  }

  body.woocommerce-account .woocommerce-MyAccount-content button.button,
  body.woocommerce-account .woocommerce-MyAccount-content input[type="submit"],
  body.woocommerce-account .woocommerce-MyAccount-content .woocommerce-Button.button {
    width: 100%;
    min-width: 0;
    height: 50px;
    font-size: 16px;
  }
}

